const STOP_WORDS = new Set([
  'a','an','and','are','as','at','be','because','been','but','by','can','do','for',
  'from','had','has','have','how','i','if','in','into','is','it','its','me','my',
  'not','of','on','or','our','should','so','that','the','their','them','then',
  'there','these','they','this','to','us','was','we','what','when','where','which',
  'who','why','will','with','you','your'
]);

function normalize(value: string): string {
  return value
    .toLowerCase()
    .normalize('NFKD')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function tokenize(value: string): string[] {
  return normalize(value)
    .split(' ')
    .filter((token) => token.length > 2 && !STOP_WORDS.has(token));
}

function scoreChunk(query: string, chunk: KnowledgeChunk): number {
  const queryTokens = tokenize(query);
  if (queryTokens.length === 0) return 0;

  const title = normalize(chunk.source);
  const body = normalize(chunk.text);
  let score = 0;

  for (const token of queryTokens) {
    if (title.includes(token)) score += 8;
    const matches = body.match(new RegExp(`\\b${token}\\b`, 'g'));
    if (matches) score += Math.min(matches.length, 6);
  }

  const phrase = normalize(query);
  if (phrase.length > 8 && body.includes(phrase)) score += 20;

  return score;
}

export function retrieveKnowledge(query: string, limit = 8): KnowledgeChunk[] {
  const ranked = KNOWLEDGE_CHUNKS
    .map((chunk) => ({ chunk, score: scoreChunk(query, chunk) }))
    .sort((a, b) => b.score - a.score);

  const relevant = ranked.filter((entry) => entry.score > 0).slice(0, limit);

  // If the query is broad, provide a small cross-section instead of no context.
  if (relevant.length === 0) {
    return KNOWLEDGE_CHUNKS.filter((_, index) => index % 14 === 0).slice(0, limit);
  }

  return relevant.map((entry) => entry.chunk);
}

export function formatKnowledge(chunks: KnowledgeChunk[]): string {
  return chunks
    .map(
      (chunk) =>
        `SOURCE: ${chunk.source} | PAGE: ${chunk.page}\n${chunk.text}`,
    )
    .join('\n\n---\n\n');
}
